package com.familyhub.data.menu

import com.familyhub.data.export.ExportDailyAssignment
import com.familyhub.data.export.ExportMenuEntry
import com.familyhub.data.export.ExportMenuTemplate
import com.familyhub.data.export.ExportMenuTemplateEntry
import com.familyhub.data.export.ExportWeeklyMenu

/**
 * Pure total-order comparators for menu records.
 *
 * Winner selection uses the **greater** value (`compare(a,b) > 0` ⇒ a wins).
 *
 * ## Field winner directions (after `updatedAt` DESC)
 *
 * ### Weekly menu
 * 1. `updatedAt` — higher wins
 * 2. `isAutoGenerated` — `false` (manual) wins over `true`
 * 3. `createdAt` — higher wins
 * 4. `id` — lexicographically lower wins
 *
 * ### Weekly menu entry
 * 1. `updatedAt` — higher
 * 2. `recipeId` — nulls last, then lex higher
 * 3. `customDish` — nulls last, then lex higher
 * 4. `servings` — higher
 * 5. `assignedMemberId` — nulls last, then lex higher
 * 6. `cookingTaskId` — nulls last, then lex higher
 * 7. `prepTaskId` — nulls last, then lex higher
 * 8. `id` — lex lower wins
 *
 * ### Menu template
 * 1. `updatedAt` — higher
 * 2. `name` — lex higher
 * 3. `createdAt` — higher
 * 4. `id` — lex lower wins
 *
 * ### Template entry (task refs pre-normalized to null before compare)
 * Same as weekly entry without cooking/prep fields.
 *
 * ### Daily assignment
 * 1. `updatedAt` — higher
 * 2. `assignedMemberId` — nulls last, then lex higher
 * 3. `rewardPoints` — nulls last, then higher
 * 4. `isRated` — `true` wins over `false`
 * 5. `id` — lex lower wins
 */
object MenuRecordComparator {

    fun compareWeeklyMenus(a: ExportWeeklyMenu, b: ExportWeeklyMenu): Int {
        compareDesc(a.updatedAt, b.updatedAt).let { if (it != 0) return it }
        // manual (false) wins → treat false as greater
        compareBooleanFalseWins(a.isAutoGenerated, b.isAutoGenerated).let { if (it != 0) return it }
        compareDesc(a.createdAt, b.createdAt).let { if (it != 0) return it }
        return compareIdAscWins(a.id, b.id)
    }

    fun compareMenuEntries(a: ExportMenuEntry, b: ExportMenuEntry): Int {
        compareDesc(a.updatedAt, b.updatedAt).let { if (it != 0) return it }
        compareNullableStringNullsLast(a.recipeId, b.recipeId).let { if (it != 0) return it }
        compareNullableStringNullsLast(a.customDish, b.customDish).let { if (it != 0) return it }
        compareDesc(a.servings.toLong(), b.servings.toLong()).let { if (it != 0) return it }
        compareNullableStringNullsLast(a.assignedMemberId, b.assignedMemberId).let { if (it != 0) return it }
        compareNullableStringNullsLast(a.cookingTaskId, b.cookingTaskId).let { if (it != 0) return it }
        compareNullableStringNullsLast(a.prepTaskId, b.prepTaskId).let { if (it != 0) return it }
        return compareIdAscWins(a.id, b.id)
    }

    fun compareMenuTemplates(a: ExportMenuTemplate, b: ExportMenuTemplate): Int {
        compareDesc(a.updatedAt, b.updatedAt).let { if (it != 0) return it }
        a.name.compareTo(b.name).let { if (it != 0) return it }
        compareDesc(a.createdAt, b.createdAt).let { if (it != 0) return it }
        return compareIdAscWins(a.id, b.id)
    }

    fun compareTemplateEntries(a: ExportMenuTemplateEntry, b: ExportMenuTemplateEntry): Int {
        val left = a.copy(cookingTaskId = null, prepTaskId = null)
        val right = b.copy(cookingTaskId = null, prepTaskId = null)
        compareDesc(left.updatedAt, right.updatedAt).let { if (it != 0) return it }
        compareNullableStringNullsLast(left.recipeId, right.recipeId).let { if (it != 0) return it }
        compareNullableStringNullsLast(left.customDish, right.customDish).let { if (it != 0) return it }
        compareDesc(left.servings.toLong(), right.servings.toLong()).let { if (it != 0) return it }
        compareNullableStringNullsLast(left.assignedMemberId, right.assignedMemberId).let { if (it != 0) return it }
        return compareIdAscWins(left.id, right.id)
    }

    fun compareDailyAssignments(a: ExportDailyAssignment, b: ExportDailyAssignment): Int {
        compareDesc(a.updatedAt, b.updatedAt).let { if (it != 0) return it }
        compareNullableStringNullsLast(a.assignedMemberId, b.assignedMemberId).let { if (it != 0) return it }
        compareNullableLongNullsLast(a.rewardPoints?.toLong(), b.rewardPoints?.toLong()).let {
            if (it != 0) return it
        }
        compareBooleanTrueWins(a.isRated, b.isRated).let { if (it != 0) return it }
        return compareIdAscWins(a.id, b.id)
    }

    fun <T> selectWinner(items: List<T>, compare: (T, T) -> Int): T {
        require(items.isNotEmpty()) { "selectWinner requires non-empty list" }
        return items.reduce { acc, next -> if (compare(acc, next) >= 0) acc else next }
    }

    /** Higher numeric value wins (`a > b` ⇒ positive). */
    private fun compareDesc(a: Long, b: Long): Int = a.compareTo(b)

    private fun compareBooleanFalseWins(a: Boolean, b: Boolean): Int = when {
        a == b -> 0
        !a && b -> 1 // false wins
        else -> -1
    }

    private fun compareBooleanTrueWins(a: Boolean, b: Boolean): Int = when {
        a == b -> 0
        a && !b -> 1
        else -> -1
    }

    private fun compareIdAscWins(a: String, b: String): Int {
        // lower lex wins ⇒ if a < b, a wins → positive
        return b.compareTo(a)
    }

    private fun compareNullableStringNullsLast(a: String?, b: String?): Int = when {
        a == null && b == null -> 0
        a == null -> -1
        b == null -> 1
        else -> a.compareTo(b)
    }

    private fun compareNullableLongNullsLast(a: Long?, b: Long?): Int = when {
        a == null && b == null -> 0
        a == null -> -1
        b == null -> 1
        else -> a.compareTo(b)
    }
}
